package com.aoo.bcg.gamespi.fsm;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class BoundedStateModelCheckerTest{enum Event{OPEN,START,FINISH}@Test void enumeratesShortSequencesAndFindsReachableDeadlock(){var checker=new BoundedStateModelChecker<RoomLifecycleState,Event>();var broken=List.of(new StateTransition<>(RoomLifecycleState.CREATED,Event.OPEN,RoomLifecycleState.WAITING,"ok","open"),new StateTransition<>(RoomLifecycleState.WAITING,Event.START,RoomLifecycleState.PLAYING,"ok","start"));var issues=checker.check(RoomLifecycleState.CREATED,broken,Set.of(RoomLifecycleState.FINISHED),4);assertEquals("NON_TERMINAL_DEADLOCK",issues.getFirst().violation());assertEquals(List.of(Event.OPEN,Event.START),issues.getFirst().eventSequence());var fixed=new ArrayList<>(broken);fixed.add(new StateTransition<>(RoomLifecycleState.PLAYING,Event.FINISH,RoomLifecycleState.FINISHED,"ok","finish"));assertTrue(checker.check(RoomLifecycleState.CREATED,fixed,Set.of(RoomLifecycleState.FINISHED),4).isEmpty());}}
